#[derive(Debug, Default)]
struct TestTitleScope {
    test_titles: FxHashSet<String>,
    describe_titles: FxHashSet<String>,
}

struct IdenticalTestTitleVisitor {
    stack: Vec<TestTitleScope>,
}

impl Default for IdenticalTestTitleVisitor {
    fn default() -> Self {
